                        cand.append((d,rr*W+cc,rr,cc))
                d,p,rr,cc=min(cand)
                dr=(rr-r)*2//max(1,d); dc=(cc-c)*2//max(1,d)
                r2,c2=r+dr//2, c+dc//2
                for s in (1,-1):
                    x,y=r2+(rr-r)*s, c2+(cc-c)*s
                    while 0<=x<H and 0<=y<W:
